     1	/** Tovu route policy; Jini owns the taxonomy, status defaults and wire serialization. */
     2	import type { Response } from 'express';
     3	import { createApiError, type GenericErrorCode, type JsonValue } from '@jini-ai/protocol';
     4	import { sendApiError, statusForError } from '@jini-ai/http-kit';
     5	
     6	/** Reply with reviewed caller-safe copy and the request tracker's existing correlation id.
     7	 * @complexity O(1); sends one JSON response, never serializes a raw exception.
     8	 */
     9	export function respondToApiError(
    10	  { res, code, message }: { res: Response; code: GenericErrorCode; message: string },
    11	  { details }: { details?: JsonValue } = {},
    12	): void {
    13	  const requestId: unknown = res.locals.requestId;
    14	  const error = createApiError({ code, message }, { ...(typeof requestId === 'string' ? { requestId } : {}), ...(details === undefined ? {} : { details }) });
    15	  sendApiError({ res, status: statusForError({ error }), error });
    16	}
