     8	import { getAuthedPrincipal } from "#src/server/inbound/admin-http/dev-auth";
     9	import type { RouteDeps } from "#src/server/routes/types";
    10	
    11	/**
    12	 * @file Admin "recent hits" read route for the `analytics` library (ADR-035, ADR-PIPE-014).
    13	 *
    14	 * Purpose:
    15	 * Registers `GET /api/admin/v1/workspaces/:workspaceId/analytics/recent-hits` — an authenticated,
    16	 * `analytics.read`-gated read straight over the ingest-side `AnalyticsSinkPort`'s raw hit buffer
    17	 * (`SqliteBufferSink` in real composition, `LocalBufferSink` in hermetic composition).
    18	 *
    19	 * IMPORTANT — this is deliberately NOT a dashboard. Only the ingest half of ADR-035 is built
    20	 * (beacon → normalize → `LocalBufferSink`); there is no rollup/aggregation/time-series query layer
    21	 * yet (that is Tier-3, explicitly deferred). So this route can only ever return a raw recent-hits
    22	 * list — no totals, no breakdowns, no charts. Do not read more into the response shape than that.
    23	 *
    24	 * How it relates to the project:
    25	 * - Mirrors `apps/website/src/server/inbound/admin-http/routes/posts/list.ts`'s registrar shape and workspace-guard convention.
    26	 * - `apps/website/src/server/runtime/composition/app.ts` gates all of `/api/admin` behind `requireAdminSession` before any admin
    27	 *   registrar runs (see `inbound/admin-http/dev-auth.ts`), same as every other admin route — but that only
    28	 *   proves *authentication*. FEAT-014/ADR-PIPE-014 closes the remaining *authorization* gap: this
    29	 *   route previously had zero per-action `authorize()` call, unlike every sibling admin route.
    30	 *   The principal-resolution → `authorize()` → 403-on-denial → proceed block below is byte-for-byte
    31	 *   the same shape used by `settings/get-effective.ts` and `integrations/list.ts` (workspace-id
    32	 *   404 check first, then authorize) — see ADR-PIPE-014 Decision §1/Enforcement.
    33	 */
    34	
    35	/** Deps this route needs: the workspace scope + authorize seam from `RouteDeps`, plus the ingest sink to read. */
    36	export type AdminAnalyticsRecentHitsDeps = Pick<RouteDeps, "workspaceId" | "authorize"> & {
    37	  analyticsSink: AnalyticsSinkPort;
    38	};
    39	
    40	/** The bounded, honest subset of a `NormalizedHit` this screen shows — raw ingest fields only. */
    41	export interface AdminAnalyticsHitResponse {
    42	  occurredAt: string;
    43	  kind: HitKind;
    44	  path: string;
    45	  referrerHost: string | null;
    46	  deviceClass: DeviceClass;
    47	  browserFamily: string | null;
    48	  eventName: string | null;
    49	}
    50	
    51	function toAdminAnalyticsHitResponse(hit: NormalizedHit): AdminAnalyticsHitResponse {
    52	  return {
    53	    occurredAt: hit.occurredAt,
    54	    kind: hit.kind,
    55	    path: hit.path,
    56	    referrerHost: hit.referrerHost,
    57	    deviceClass: hit.deviceClass,
    58	    browserFamily: hit.browserFamily,
    59	    eventName: hit.eventName,
    60	  };
    61	}
    62	
    63	/**
    64	 * Parses the `?limit=` query param into a finite number, or `undefined` when absent/unparsable —
    65	 * the sink's `list()` owns the actual clamping/default, this just guards against handing it a
    66	 * non-numeric string.
    67	 */
    68	function parseLimitParam({ raw }: { raw: unknown }, _optional = {}): number | undefined {
    69	  if (typeof raw !== "string" || raw.trim() === "") return undefined;
    70	  const parsed = Number(raw);
    71	  return Number.isFinite(parsed) ? parsed : undefined;
    72	}
    73	
    74	export function registerAdminAnalyticsRecentHitsRoute(app: Express, deps: AdminAnalyticsRecentHitsDeps): void {
    75	  app.get("/api/admin/v1/workspaces/:workspaceId/analytics/recent-hits", async (req, res) => {
    76	    if (String(req.params.workspaceId ?? "") !== deps.workspaceId) {
    77	      respondToApiError({ res, code: "NOT_FOUND", message: "workspace was not found" });
    78	      return;
    79	    }
    80	
    81	    try {
    82	      const principal = getAuthedPrincipal(res);
    83	      const authResult = await deps.authorize({
    84	        principalId: principal.id,
    85	        permission: "analytics.read",
    86	        workspaceId: deps.workspaceId,
    87	        entityType: "analytics-hit",
    88	      });
    89	      if (!authResult.allowed) {
    90	        respondToApiError({ res, code: "FORBIDDEN", message: `principal '${principal.id}' is not authorized for 'analytics.read' (${authResult.reason})` }, {
    91	          details: { permission: "analytics.read", reason: authResult.reason },
    92	        });
    93	        return;
    94	      }
    95	
    96	      const limit = parseLimitParam({ raw: req.query.limit });
    97	      const hits = (await deps.analyticsSink.list({}, { limit })).map(toAdminAnalyticsHitResponse);
    98	      res.json({ hits });
    99	    } catch (err) {
   100	      // Keep shared redacted diagnostics without replacing the canonical analytics wire contract.
   101	      const failure = adminFailureResponse({ error: err, tracker: res.locals.adminFailureTracker }, {
   102	        operation: "analytics/recent-hits", method: req.method, route: req.route.path,
   103	        discloseDetails: !!res.locals.principal,
   104	      });
   105	      res.status(failure.status).json({ error: {
   106	        code: failure.body.code, message: failure.body.error,
   107	        ...(res.locals.principal ? { details: { errorId: failure.body.errorId, ...failure.body.details } } : {}),
   108	        ...(typeof res.locals.requestId === "string" ? { requestId: res.locals.requestId } : {}),
   109	      } });
   110	    }
   111	  });
   112	}
