     1	import { describeErrorForLog } from "#src/contracts/core/model-facing-tool-errors";
     2	import type { ExternalMcpOperations } from "#src/features/external-mcp/operations-tools";
     3	
     4	/** Live in-process accounting. The federation transport owns remote errors and their tracing. */
     5	export interface ServerAdmissionsReader {
     6	  readonly awaitFederation?: (required: { timeoutMs: number }, optional?: Record<string, never>) => Promise<{ readonly settled: boolean }>;
     7	  readonly readAdmissions?: () => Promise<{ readonly connections: unknown; readonly configFailures?: unknown }>;
     8	}
     9	
    10	/** One failure contract for missing composition, a connecting server or a failed read.
    11	 * Keep the legacy code until the admin client's unavailable-state contract migrates too:
    12	 * an unavailable report must never look like an empty admitted roster. */
    13	function unavailable(): Awaited<ReturnType<ExternalMcpOperations["admissions"]>> {
    14	  return { ok: false, body: { error: "the server's external MCP admissions are unavailable — try again shortly", code: "AGENT_DAEMON_UNAVAILABLE" } };
    15	}
    16	
    17	/** Read the server's single federation after its bounded admission wait; never wake a daemon.
    18	 * @param required - The existing surface's wait and live-report ports; absent ports fail closed.
    19	 * @returns Current reports, preserving optional config failures, or the legacy distinguishable failure.
    20	 * @example readServerAdmissions({ awaitFederation: surface.awaitFederation, readAdmissions })
    21	 * @complexity O(1) beyond federation startup and the report reader; the wait is bounded to 5 seconds.
    22	 */
    23	export async function readServerAdmissions(
    24	  { awaitFederation, readAdmissions }: ServerAdmissionsReader,
    25	  _options: Record<string, never> = {},
    26	): ReturnType<ExternalMcpOperations["admissions"]> {
    27	  if (!awaitFederation || !readAdmissions) return unavailable();
    28	  try {
    29	    if (!(await awaitFederation({ timeoutMs: 5_000 })).settled) return unavailable();
    30	    const report = await readAdmissions();
    31	    if (!Array.isArray(report.connections)) return unavailable();
    32	    if (report.configFailures !== undefined && !Array.isArray(report.configFailures)) return unavailable();
    33	    return report.configFailures === undefined
    34	      ? { ok: true, connections: report.connections }
    35	      : { ok: true, connections: report.connections, configFailures: report.configFailures };
    36	  } catch (error) {
    37	    // Fixed metadata only: an opaque transport failure must not expose credentials to the client.
    38	    console.error("external-mcp server admissions read failed", describeErrorForLog({ err: error }));
    39	    return unavailable();
    40	  }
    41	}
