     3	import { connectMcpHttpSession, createFetchMcpHttpExchange } from "../../../assistant/index.js";
     4	import { ExternalMcpReauthRequiredError, externalMcpSettingsDeepLink } from "../../../features/external-mcp/external-mcp-oauth.js";
     5	import { readEnabledExternalMcpConfigs, toResolvedFederatedConnections } from "../../../features/external-mcp/external-mcp-store.js";
